mapper.select:
SELECT a.id, a.name, a.episode_count, a.broadcast_type_id, a.adaptation_type_id, a.region_id, a.air_date, a.cover_image_url, a.status, a.created_at, a.updated_at FROM anime a LEFT JOIN personal_rating pr ON pr.target_type = 'ANIME' AND pr.target_id = a.id
AND ( LOWER(a.name) LIKE '%' || LOWER(#{pageDTO.keyword}) || '%' OR EXISTS ( SELECT 1 FROM alias al WHERE al.target_type = 'ANIME' AND al.target_id = a.id AND LOWER(al.alias_name) LIKE '%' || LOWER(#{pageDTO.keyword}) || '%' ) OR EXISTS ( SELECT 1 FROM series_item si INNER JOIN series s ON s.id = si.series_id WHERE si.work_type = 'anime' AND si.work_id = a.id AND LOWER(s.name) LIKE '%' || LOWER(#{pageDTO.keyword}) || '%' ) )
AND EXISTS ( SELECT 1 FROM tag_relation tr WHERE tr.target_type = 'ANIME' AND tr.target_id = a.id AND tr.tag_id IN
#{tagId}
)
AND ( SELECT COUNT(DISTINCT tr.tag_id) FROM tag_relation tr WHERE tr.target_type = 'ANIME' AND tr.target_id = a.id AND tr.tag_id IN
#{tagId}
) = #{tagCount}
AND a.broadcast_type_id = #{pageDTO.broadcastTypeId}
AND a.adaptation_type_id = #{pageDTO.adaptationTypeId}
AND a.air_date >= #{startDate}
AND a.air_date <= #{endDate}
AND a.status = #{pageDTO.status}
AND a.region_id = #{pageDTO.regionId}
AND EXISTS ( SELECT 1 FROM company_relation cr WHERE cr.target_type = 'ANIME' AND cr.target_id = a.id AND cr.company_id = #{pageDTO.companyId} )
AND pr.score >= #{pageDTO.ratingMin}
AND pr.score <= #{pageDTO.ratingMax}
ORDER BY
pr.score
a.air_date
ASC
DESC
NULLS LAST, a.id DESC
